public void insert()
{
    if(!this.NVTransactionYear)
    {
        this.NVTransactionYear = year(this.TransactionDate);
    }

    next insert();

    if (!this.isTempDb())
    {
        this.calcAdditionalAccrual();
    }
}

public void calcAdditionalAccrual()
{
    if(this.TransactionType == LeaveTransactionType::Accrual
        && this.LeavePlan
        && this.NVLeaveCategory == NVLeaveCategory::None)
    {
        NVLeaveAccrualAdditionalProcess additionalAccrualProcess  = NVLeaveAccrualAdditionalProcess::construct();

        additionalAccrualProcess.initBankTransaction(this);
        additionalAccrualProcess.process();
    }

    if(this.TransactionType == LeaveTransactionType::Request)
    {
        NVLeaveRequestAdditionalProcess additionalRequestProcess = NVLeaveRequestAdditionalProcess::construct();

        additionalRequestProcess.initBankTransaction(this);
        additionalRequestProcess.process();
    }
}
